import sys, json
import pandas as pd
import numpy as np

def to_float(x):
    if pd.isna(x):
        return None
    return float(x)

def main():
    path = sys.argv[1]
    df = pd.read_csv(path)

    facts = []

    # ---------- TOTALS ----------
    total_rev_tw = df['Revenue_TW'].sum(skipna=True)
    total_rev_lw = df['Revenue_LW'].sum(skipna=True)
    total_rev_ly = df['Revenue_LY'].sum(skipna=True)
    total_units_tw = df['Units_TW'].sum(skipna=True)
    total_units_lw = df['Units_LW'].sum(skipna=True)
    total_orders_tw = df['Orders_TW'].sum(skipna=True)
    total_orders_lw = df['Orders_LW'].sum(skipna=True)

    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "TW",
        "value": round(to_float(total_rev_tw), 2),
        "formula": "sum(Revenue_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "LW",
        "value": round(to_float(total_rev_lw), 2),
        "formula": "sum(Revenue_LW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "LY",
        "value": round(to_float(total_rev_ly), 2),
        "formula": "sum(Revenue_LY)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "TW",
        "value": round(to_float(total_units_tw), 2),
        "formula": "sum(Units_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "LW",
        "value": round(to_float(total_units_lw), 2),
        "formula": "sum(Units_LW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "TW",
        "value": round(to_float(total_orders_tw), 2),
        "formula": "sum(Orders_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "LW",
        "value": round(to_float(total_orders_lw), 2),
        "formula": "sum(Orders_LW)"
    })

    if total_rev_lw and not pd.isna(total_rev_lw) and total_rev_lw != 0:
        total_wow = (total_rev_tw - total_rev_lw) / total_rev_lw * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "WoW",
            "value": round(to_float(total_wow), 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LW)) / sum(Revenue_LW) * 100"
        })

    if total_rev_ly and not pd.isna(total_rev_ly) and total_rev_ly != 0:
        total_yoy = (total_rev_tw - total_rev_ly) / total_rev_ly * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "YoY",
            "value": round(to_float(total_yoy), 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LY)) / sum(Revenue_LY) * 100"
        })

    # ---------- TOP ENTITIES BY REVENUE_TW ----------
    top_rev = df.dropna(subset=['Revenue_TW']).sort_values('Revenue_TW', ascending=False).head(5)
    for _, row in top_rev.iterrows():
        facts.append({
            "entity": row['Entity'], "metric": "revenue", "period": "TW",
            "value": round(to_float(row['Revenue_TW']), 2),
            "formula": "Revenue_TW"
        })

    # ---------- TOP ENTITIES BY SHARE ----------
    if 'Share_Pct' in df.columns:
        top_share = df.dropna(subset=['Share_Pct']).sort_values('Share_Pct', ascending=False).head(3)
        for _, row in top_share.iterrows():
            facts.append({
                "entity": row['Entity'], "metric": "share", "period": "TW",
                "value": round(to_float(row['Share_Pct']), 1),
                "formula": "Share_Pct"
            })

    # ---------- RANK 1 ENTITY ----------
    if 'Rank' in df.columns:
        rank1 = df[df['Rank'] == 1]
        for _, row in rank1.iterrows():
            facts.append({
                "entity": row['Entity'], "metric": "rank", "period": "TW",
                "value": to_float(row['Rank']),
                "formula": "Rank"
            })

    # ---------- TOP WoW GAINERS ----------
    wow_df = df.dropna(subset=['WoW_Pct']).sort_values('WoW_Pct', ascending=False).head(5)
    for _, row in wow_df.iterrows():
        facts.append({
            "entity": row['Entity'], "metric": "revenue", "period": "WoW",
            "value": round(to_float(row['WoW_Pct']), 1),
            "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
        })

    # ---------- TOP WoW DECLINERS ----------
    wow_decline = df.dropna(subset=['WoW_Pct']).sort_values('WoW_Pct', ascending=True).head(3)
    for _, row in wow_decline.iterrows():
        facts.append({
            "entity": row['Entity'], "metric": "revenue", "period": "WoW",
            "value": round(to_float(row['WoW_Pct']), 1),
            "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
        })

    # ---------- TOP YoY GAINERS ----------
    yoy_df = df.dropna(subset=['YoY_Pct']).sort_values('YoY_Pct', ascending=False).head(5)
    for _, row in yoy_df.iterrows():
        facts.append({
            "entity": row['Entity'], "metric": "revenue", "period": "YoY",
            "value": round(to_float(row['YoY_Pct']), 1),
            "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100"
        })

    # ---------- TOP YoY DECLINERS ----------
    yoy_decline = df.dropna(subset=['YoY_Pct']).sort_values('YoY_Pct', ascending=True).head(2)
    for _, row in yoy_decline.iterrows():
        facts.append({
            "entity": row['Entity'], "metric": "revenue", "period": "YoY",
            "value": round(to_float(row['YoY_Pct']), 1),
            "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100"
        })

    # Trim to 25 facts max
    facts = facts[:25]

    print(json.dumps(facts))

if __name__ == "__main__":
    main()
